var activeClass = new Packages.java.util.ArrayList();
var stage = jelly.jvar_stage;
stage == 1 ? activeClass.add("active") : activeClass.add("disabled");
stage == 2 ? activeClass.add("active") : activeClass.add("disabled");
stage == 3 ? activeClass.add("active") : activeClass.add("disabled");
