var ariaText = new Packages.java.util.ArrayList();
var stage = jelly.jvar_stage;

if (stage == 1) {
	ariaText.add(gs.getMessage('Identification step'));
	ariaText.add(gs.getMessage('Verification pending'));
	ariaText.add(gs.getMessage('Reset pending'));
} else if (stage == 2) {
	ariaText.add(gs.getMessage('Identification completed'));
	ariaText.add(gs.getMessage('Verification step'));
	ariaText.add(gs.getMessage('Reset pending'));
} else {
	ariaText.add(gs.getMessage('Identification completed'));
	ariaText.add(gs.getMessage('Verification completed'));
	ariaText.add(gs.getMessage('Reset step'));
}
ariaText;
